<template><view class="page"><text class="title">我的</text><view class="card"><view class="user"><view class="avatar">{{name[0]}}</view><view><strong>{{name}}</strong><text>{{email}}</text></view></view><button @tap="edit">个人资料　›</button><button>账号安全　›</button><button>提醒设置　›</button><button class="logout" @tap="logout">退出登录</button></view></view></template><script setup>import{ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{supabase,currentUser}from'../../lib/supabase';const name=ref('用'),email=ref('');onShow(async()=>{let u=await currentUser();name.value=u?.user_metadata.nickname||'用户';email.value=u?.email||''});function edit(){uni.showModal({title:'修改昵称',editable:true,success:async r=>{if(r.confirm&&r.content){await supabase.auth.updateUser({data:{nickname:r.content}});name.value=r.content}}})}async function logout(){await supabase.auth.signOut();uni.reLaunch({url:'/pages/login/login'})}</script><style scoped>.page{padding:30px 18px}.title{font-size:24px;font-weight:700}.card{background:#fff;border-radius:18px;padding:16px;margin-top:20px}.user{display:flex;align-items:center;gap:12px;padding-bottom:18px;border-bottom:1px solid #edf2f5}.avatar{width:50px;height:50px;border-radius:50%;background:#aee0fb;display:flex;align-items:center;justify-content:center;font-weight:700}.user view:last-child{display:flex;flex-direction:column}.user text{font-size:12px;color:#8ca2af;margin-top:4px}.card button{text-align:left;background:#fff;padding:15px 0;border-bottom:1px solid #edf2f5}.logout{color:#d65f5f}</style>
